style.css:
/* Paperlight — Material Book | Global */
/* i really want this to be global */

/* Customizable theme variables */
:root {
  color-scheme: light dark;

  --my-bg: #f7f5fa;
  --my-paper: #fffbff;
  --my-text: #29252f;
  --my-muted: #77717e;
  --my-accent: #6750a4;
  --my-border: #e8e1ec;

  --my-reading-width: 760px;
  --my-reading-size: 19px;
  --my-line-height: 1.85;
}

/* Automatic dark theme */
@media (prefers-color-scheme: dark) {
  :root {
    --my-bg: #141218;
    --my-paper: #211f26;
    --my-text: #e9e1ec;
    --my-muted: #b0a8b5;
    --my-accent: #d0bcff;
    --my-border: #39343f;
  }
}

/* Page */
html, body {
  background: var(--my-bg) !important;
  color: var(--my-text) !important;
  font-family: "Google Sans", "Google Sans Flex",
               "Roboto", sans-serif !important;
}

/* Reading area */
main, article, [role="main"] {
  max-width: var(--my-reading-width) !important;
  margin-inline: auto !important;
  color: var(--my-text) !important;
}

/* Paragraphs */
article p, main p, [role="main"] p {
  font-size: var(--my-reading-size) !important;
  line-height: var(--my-line-height) !important;
  font-weight: 400 !important;
  color: var(--my-text) !important;
}

/* Headings */
h1, h2, h3, h4 {
  font-family: "Google Sans", "Roboto", sans-serif !important;
  font-weight: 650 !important;
  letter-spacing: -0.035em !important;
  line-height: 1.3 !important;
  color: var(--my-text) !important;
}

/* Links */
a {
  color: var(--my-accent) !important;
}

/* Images */
article img, main img {
  border-radius: 16px !important;
}

/* Text selection */
::selection {
  background: var(--my-accent) !important;
  color: white !important;
}
